  slug text,
  nome_completo text,
  nome_urna text,
  ano_eleicao integer,
  resultado text,
  sq_candidato text,
  uf_candidatura text,
  total_arrecadado numeric,
  total_fundo_partidario numeric,
  total_fundo_eleitoral numeric,
  total_pessoa_fisica numeric,
  total_recursos_proprios numeric,
  maiores_doadores jsonb,
  fonte_url text,
  detalhe text
